/** Reviewed against sdk/kotlin/src/nimby. These are author contracts, not inferred labels. */
export const nativeApiContracts: Record<string, readonly [string, string]> = {}
export const nativeContractGuides: Record<string, readonly string[]> = {}
let related: readonly string[] = ['/mods/signaux']
function entry(id: string, fr: string, en: string) {
  const key = `native:nimby:${id}`
  if (nativeApiContracts[key]) throw new Error(`Duplicate Native contract: ${key}`)
  nativeApiContracts[key] = [fr, en]
  nativeContractGuides[key] = related
}
function properties(owner: string, rows: readonly (readonly [string, string, string])[], kind = 'val') {
  for (const [name, fr, en] of rows) entry(`${kind}:${owner}.${name}`, fr, en)
}

related = ['/mods/options']
