entry('class:DrivingInput', 'Situation d’entrée d’un calcul de conduite. Les positions sont longitudinales, les vitesses en m/s ; fresh et routeKnown doivent être traités avant de produire un plan utilisable.', 'Input situation for a driving calculation. Positions are longitudinal and speeds are in m/s; handle fresh and routeKnown before producing a usable plan.')
properties('DrivingInput', [
  ['headM', 'Position longitudinale de la tête en mètres, dans le même repère que les contraintes.', 'Longitudinal head position in metres, in the same reference as constraints.'],
  ['speedMps', 'Vitesse courante fournie au calcul, en mètres par seconde.', 'Current speed supplied to the calculation, in metres per second.'],
  ['lineSpeedMps', 'Limite de ligne fournie au calcul, en m/s, indépendante du maximum du matériel.', 'Line-speed limit supplied to the calculation, in m/s, independent of the rolling-stock maximum.'],
  ['fresh', 'Validité temporelle des données d’entrée ; false par défaut. Le callback doit décider d’un repli lorsque les données sont périmées.', 'Temporal validity of input data; defaults to false. The callback must choose a fallback for stale data.'],
  ['routeKnown', 'Indique si le parcours nécessaire au calcul est connu ; false par défaut ne permet pas de supposer une voie libre.', 'Indicates whether the route needed for calculation is known; the default false cannot imply a clear track.'],
  ['onSight', 'Indique une situation de marche à vue pour le calcul ; ne crée aucune permission de franchissement.', 'Indicates an on-sight situation for calculation; grants no permission to pass a signal.'],
  ['visibleClearM', 'Distance physiquement libre connue en mètres, ou null si indisponible. null ne signifie pas une distance infinie.', 'Known physically clear distance in metres, or null when unavailable. null does not mean infinite distance.'],
])
entry('class:DrivingPlan', 'Résultat de calcul ou de diagnostic renvoyé par plan. Il ne commande pas directement le train ; la conduite en jeu utilise les DrivingRule publiées pour les signaux.', 'Calculation or diagnostic result returned by plan. It does not directly command the train; in-game driving uses the DrivingRule values published for signals.')
properties('DrivingPlan', [
  ['available', 'true seulement si le callback fournit un résultat exploitable. false par défaut : les autres zéros ne constituent pas une consigne d’arrêt.', 'true only when the callback provides a usable result. Defaults to false: other zeroes are not a stop command.'],
  ['speedCeilingMps', 'Plafond calculé en m/s, à interpréter seulement lorsque available=true.', 'Calculated speed ceiling in m/s, meaningful only when available=true.'],
  ['serviceDecelerationMps2', 'Décélération de service retenue par le calcul, en m/s².', 'Service deceleration selected by the calculation, in m/s².'],
  ['accelerationMps2', 'Accélération signée proposée par le calcul, en m/s² ; négative pour une décélération.', 'Signed acceleration proposed by the calculation, in m/s²; negative for deceleration.'],
  ['brakingRequired', 'Indique que le planificateur estime un freinage nécessaire ; ce diagnostic n’actionne pas les freins.', 'Indicates that the planner considers braking necessary; this diagnostic does not apply brakes.'],
  ['limitingSource', 'Source de la contrainte limitante choisie par le planificateur ; zéro par défaut si aucune n’est renseignée.', 'Limiting constraint source selected by the planner; defaults to zero when none is supplied.'],
])
entry('class:DrivingFlag', 'Politiques qui composent une DrivingRule. Préférez les helpers AutomaticDriving, qui vérifient les combinaisons et les vitesses attendues.', 'Policies composing a DrivingRule. Prefer AutomaticDriving helpers, which validate expected combinations and speeds.')
entry('val:DrivingFlag.bit', 'Valeur numérique associée au drapeau. Les mods utilisent le Set<DrivingFlag> et les helpers ; aucun masque manuel n’est nécessaire.', 'Numeric value associated with the flag. Mods use Set<DrivingFlag> and helpers; no manual mask is needed.')
for (const [name, fr, en] of [
  ['Clear', 'Marque une permission Clear servant de point de libération aux politiques qui la demandent.', 'Marks Clear permission as a release point for policies that require it.'],
  ['HoldToClear', 'Conserve une restriction jusqu’au passage effectif d’un Clear puis au dégagement de ce point par la queue.', 'Retains a restriction until a Clear is actually passed and the rear then clears that point.'],
  ['Stop', 'Demande un arrêt au point visé. Seul, ce drapeau n’autorise pas de franchissement après l’arrêt.', 'Requests a stop at the target point. Alone, this flag does not permit passing after stopping.'],
  ['FollowTarget', 'Permet de suivre la vitesse numérique déclarée par la cible d’une annonce ; n’interprète pas sa couleur.', 'Allows following the numeric speed declared by an announcement target; does not interpret its colour.'],
  ['OnSight', 'Politique de marche limitée avec freinage sur l’espace physiquement libre jusqu’au prochain signal.', 'Restricted-movement policy braking for physically clear space until the next signal.'],
  ['StopThenProceed', 'Avec Stop et OnSight, exige un arrêt préalable avant une entrée restreinte explicitement autorisée.', 'Together with Stop and OnSight, requires a prior stop before explicitly permitted restricted entry.'],
  ['CancelAtNextClear', 'Politique optionnelle d’annulation d’une annonce au prochain Clear. Le helper l’accepte seulement avec FollowTarget à deux signaux.', 'Optional policy cancelling an announcement at the next Clear. The helper accepts it only with FollowTarget and a target two signals ahead.'],
  ['ApproachPassable', 'Autorise le franchissement du signal courant selon la vitesse mémorisée, sans lever les autres restrictions.', 'Permits passing the current signal according to the remembered speed, without removing other restrictions.'],
] as const) entry(`enum-entry:DrivingFlag.${name}`, fr, en)
entry('class:DrivingRule', 'Consigne déclarative de conduite associée à une indication. Privilégiez AutomaticDriving pour valider cible, vitesses et permissions. Construire une valeur ne la publie pas.', 'Declarative driving rule associated with an indication. Prefer AutomaticDriving to validate target, speeds and permissions. Constructing a value does not publish it.')
properties('DrivingRule', [
  ['speedMps', 'Vitesse cible en m/s ; zéro pour un arrêt. La valeur −1 par défaut signifie qu’aucun plafond numérique n’est fourni, notamment pour Clear.', 'Target speed in m/s; zero for a stop. The default −1 means no numeric ceiling is supplied, notably for Clear.'],
  ['reopenedSpeedMps', 'Vitesse de remplacement à la réouverture d’une cible, ou plafond après entrée pour la marche restreinte ; en m/s. Le helper choisi définit ce rôle.', 'Replacement speed when a target reopens, or the post-entry ceiling for restricted movement; in m/s. The selected helper defines its role.'],
  ['signalsAhead', 'Position de la cible : 0 pour le signal courant, 1 ou 2 pour un signal aval. Les helpers limitent les valeurs selon la politique.', 'Target position: 0 for this signal, 1 or 2 for a downstream signal. Helpers restrict values for each policy.'],
  ['flags', 'Ensemble explicite des politiques de passage, d’arrêt et de libération. Un ensemble vide ne donne aucune permission implicite.', 'Explicit set of passage, stop and release policies. An empty set grants no implicit permission.'],
])

related = ['/mods/signaux', '/mods/conduite']
entry('class:SignallingMod', 'Base d’un mod de signalisation. Utilisez signalMod et signalModel pour construire son implémentation ; les méthodes de calcul restent appelables avec des valeurs copiées dans les tests.', 'Base of a signalling mod. Use signalMod and signalModel to construct its implementation; calculation methods remain callable with copied values in tests.')
entry('fun:SignallingMod.prepareNetwork(List<Signal>)', 'Transformation pure des réglages effectifs du réseau observé. Conservez ordre, nombre, identités, liens, types et observations ; les valeurs dérivées ne sont pas sauvegardées. Par défaut, retourne la liste reçue.', 'Pure transformation of effective settings in the observed network. Preserve order, count, identities, links, types and observations; derived values are not saved. Returns its input list by default.')
properties('SignallingMod', [
  ['textureSet', 'Catalogue de la déclaration à un seul type. Pour plusieurs modèles, utilisez signalTypes et le catalogue de chaque SignalType.', 'Catalogue of a single-type declaration. For multiple models, use signalTypes and each SignalType’s catalogue.'],
  ['checkboxes', 'Réglages de la déclaration à un seul type. Les nouveaux modèles enregistrent leurs propres cases dans signalModel.', 'Settings of a single-type declaration. New models register their own checkboxes in signalModel.'],
  ['signalTypes', 'Types constructibles déclarés par le mod. Ils doivent posséder des identifiants et catalogues distincts, validés avant utilisation.', 'Constructible types declared by the mod. They must have distinct identifiers and catalogues, validated before use.'],
  ['maximumLineSpeed', 'Option de conduite remplaçant le plafond de marche lié à l’horaire par le maximum du matériel. Limites de voie et cibles de freinage restent applicables. false par défaut ; peut concerner aussi les trains sans contrainte de signal du mod.', 'Driving option replacing the timetable cruising ceiling with the rolling-stock maximum. Track limits and braking targets still apply. Defaults to false; can also affect trains without this mod’s signal constraints.'],
  ['diagnosticFile', 'Nom du fichier de diagnostic des défauts du mod ; nimby-kotlin-faults.jsonl par défaut. Il ne remplace pas les journaux d’actions de ToolContext.log.', 'Filename for the mod’s fault diagnostics; defaults to nimby-kotlin-faults.jsonl. Does not replace action logs written with ToolContext.log.'],
  ['unknownDecision', 'Repli de la déclaration par défaut lorsque le calcul isolé ne fournit pas d’indication. Pour un mod multi-modèles, demander unknownDecision(type).', 'Default declaration’s fallback when isolated calculation produces no indication. For a multi-model mod, request unknownDecision(type).'],
  ['invalidNetworkDecision', 'Repli de la déclaration par défaut pour un lien manquant ou cyclique nécessaire au calcul. La surcharge avec type choisit le modèle courant.', 'Default declaration’s fallback for a missing or cyclic link required by calculation. The overload with type selects the current model.'],
  ['modelLocalIndications', 'Indique que les indications conservent l’identité de leur modèle. Fourni par signalMod ; les auteurs lisent les décisions avec indication et of.', 'Indicates that indications retain model identity. Supplied by signalMod; authors read decisions through indication and of.'],
])
entry('fun:SignallingMod.migrateSettings(String,Map<String,Boolean>)', 'Convertit les clés effectivement enregistrées d’un type lors du chargement du profil. Le SDK complète ensuite les défauts ; ne pas inventer ici des valeurs pour les clés absentes.', 'Converts the keys actually saved for a type when loading its profile. The SDK fills defaults afterwards; do not invent values for absent keys here.')
entry('fun:SignallingMod.unknownDecision(String)', 'Renvoie le repli d’observation du type demandé. Ce résultat opaque se lit avec indication pour retrouver ses enums.', 'Returns the requested type’s observation fallback. Read this opaque result with indication to recover its enums.')
entry('fun:SignallingMod.invalidNetworkDecision(String)', 'Renvoie le repli de réseau invalide du modèle demandé, notamment quand une dépendance aval ne peut pas être résolue.', 'Returns the requested model’s invalid-network fallback, notably when a downstream dependency cannot be resolved.')
entry('fun:SignallingMod.indication(Decision)', 'Décode une décision produite par les modèles indépendants de ce mod. null signifie un code non reconnu ou une implémentation sans cette lecture ; utilisez ensuite of(model).', 'Decodes a decision produced by this mod’s independent models. null means an unrecognized code or an implementation without this reader; then use of(model).')
entry('fun:SignallingMod.evaluate(Map<String,Boolean>,Observation)', 'Calcule une indication isolée du type par défaut, sans résoudre de réseau. Pour plusieurs types, préférez la surcharge avec type ; ce calcul ne publie rien en jeu.', 'Calculates an isolated indication for the default type, without resolving a network. For multiple types, prefer the overload with type; this calculation publishes nothing in-game.')
entry('fun:SignallingMod.evaluate(String,Map<String,Boolean>,Observation)', 'Calcule le type demandé à partir de réglages et d’une observation copiés. Utilise son callback evaluate ou sa règle isolée ; ne remplace pas evaluateNetwork pour les dépendances aval.', 'Calculates the requested type from copied settings and observation. Uses its evaluate callback or isolated rule; does not replace evaluateNetwork for downstream dependencies.')
entry('fun:SignallingMod.decide(Signal,Decision?)', 'Étape pure de résolution : next=null au premier appel. Retourner une décision conclut localement ; retourner null demande la résolution du voisin. Un second null utilise le repli de réseau invalide.', 'Pure resolution step: next=null on the first call. Returning a decision concludes locally; returning null requests neighbour resolution. A second null uses the invalid-network fallback.')
entry('fun:SignallingMod.fromLive(Signal)', 'Prépare la valeur observée avec le callback prepareObservation du type. Le comportement par défaut est l’identité ; cette transformation ne modifie pas le signal dans la partie.', 'Prepares an observed value through the type’s prepareObservation callback. Defaults to identity; this transformation does not change the signal in the game.')
entry('fun:SignallingMod.texture(Decision,Long,Long)', 'Choisit un chemin d’image déclaré à partir de l’indication, du temps simulé et de la demi-période en millisecondes. Pour une animation usuelle, préférez appearance avec steady ou blink.', 'Selects a declared image path from the indication, simulation time and half-period in milliseconds. For ordinary animation, prefer appearance with steady or blink.')
entry('fun:SignallingMod.animation(Decision)', 'Renvoie la description d’affichage déclarée avec appearance. null conserve la sélection via texture ; la description ne change aucune règle de conduite.', 'Returns the appearance description declared through appearance. null retains selection through texture; the description changes no driving rule.')
entry('fun:SignallingMod.forcedDecision(Int)', 'Demande une indication de recette autorisée pour le type par défaut. Le code est un ordinal local ; null refuse le forçage, notamment sans allowForcedAspect.', 'Requests a permitted test indication for the default type. The code is a local ordinal; null rejects forcing, notably without allowForcedAspect.')
entry('fun:SignallingMod.forcedDecision(String,Int)', 'Demande au modèle indiqué d’autoriser un aspect de recette. Le callback choisit aussi le motif ; null refuse. N’utilisez pas un code Decision.aspect brut.', 'Asks the selected model to permit a test aspect. The callback also selects the reason; null rejects it. Do not use a raw Decision.aspect code.')
entry('fun:SignallingMod.drivingRule(Decision)', 'Lit la consigne explicitement choisie par le modèle pour cette décision. null indique qu’aucune consigne n’est fournie ; aucune vitesse n’est déduite de l’image.', 'Reads the driving rule explicitly selected by the model for this decision. null means no rule is supplied; no speed is inferred from the image.')
entry('fun:SignallingMod.isFault(Decision)', 'Classe la décision comme défaut selon le callback faults du mod. Ce classement de diagnostic ne choisit pas automatiquement une image ou une consigne.', 'Classifies the decision as a fault using the mod’s faults callback. This diagnostic classification does not automatically select an image or driving rule.')
entry('fun:SignallingMod.isActive(Decision)', 'Indique si le mod gère activement cette indication selon activeWhen ; true par défaut. Il s’agit de l’activité du modèle, pas de l’occupation physique.', 'Indicates whether the mod actively manages this indication according to activeWhen; defaults to true. Describes model activity, not physical occupancy.')
entry('fun:SignallingMod.aspectName(Int)', 'Libellé de diagnostic d’un aspect appartenant à ce mod. Avec les modèles indépendants, utilisez la valeur encodée du résultat, sans fabriquer d’ordinal global.', 'Diagnostic label for an aspect belonging to this mod. With independent models, use the encoded result value without inventing a global ordinal.')
entry('fun:SignallingMod.reasonName(Int)', 'Libellé de diagnostic du motif, choisi par reasonNames. Le motif explique la décision ; il ne vaut pas une permission de mouvement.', 'Diagnostic reason label selected by reasonNames. The reason explains the decision; it is not a movement permission.')
entry('fun:SignallingMod.plan(Vehicle,DrivingSettings,DrivingInput,List<Constraint>)', 'Exécute le callback drivingPlan sur des valeurs copiées. Sans callback, renvoie un DrivingPlan indisponible. Le résultat est consultatif et n’actionne pas la conduite du train.', 'Runs the drivingPlan callback on copied values. Without a callback, returns an unavailable DrivingPlan. The result is advisory and does not control the train.')
entry('val:maximumSignalNetworkSize', 'Limite de 4096 signaux pour un appel au résolveur Kotlin. Une liste plus grande est refusée ; ce nombre n’est pas une promesse de taille maximale de carte.', 'Limit of 4096 signals per Kotlin resolver call. Larger lists are rejected; this is not a maximum-map-size promise.')
entry('fun:SignallingMod.prepareObservedNetwork(List<Signal>)', 'Valide taille, types et identités de la liste, puis contrôle que prepareNetwork conserve les liens et observations. La préparation peut dériver des réglages effectifs. Les liens absents ou cycliques sont traités ensuite par evaluateNetwork.', 'Validates the list’s size, types and identities, then checks that prepareNetwork preserves links and observations. Preparation may derive effective settings. Missing or cyclic links are handled afterwards by evaluateNetwork.')
entry('fun:SignallingMod.evaluateNetwork(List<Signal>)', 'Résout les décisions dans l’ordre de la liste fournie, après préparation validée. Les décisions locales terminent immédiatement ; les dépendances manquantes ou cycliques utilisent invalidNetwork. Fonction pure adaptée aux tests.', 'Resolves decisions in input-list order after validated preparation. Local decisions finish immediately; missing or cyclic dependencies use invalidNetwork. A pure function suitable for tests.')

related = ['/mods/paquet-genere', '/mods/metadonnees-traduites']
entry('class:ModInfo', 'Identité du paquet générée depuis mod.json sous nimby.mod.modInfo. Réutilisez cette valeur dans createMod pour éviter de dupliquer identifiant et nom.', 'Package identity generated from mod.json as nimby.mod.modInfo. Reuse it in createMod to avoid duplicating the identifier and name.')
properties('ModInfo', [
  ['id', 'Identifiant technique stable du paquet, issu de mod.json ; utilisé pour déclarer le mod et ses services.', 'Stable technical package identifier from mod.json; used to declare the mod and its services.'],
  ['title', 'Nom issu de mod.json, utilisé comme titre du groupe dans Options → NRF Hub avec toolMod(modInfo) ou signalMod(modInfo). metadata(name=...) personnalise séparément le nom des listes de mods du jeu.', 'Name from mod.json, used as the group heading in Options → NRF Hub with toolMod(modInfo) or signalMod(modInfo). metadata(name=...) separately customizes the name in the game’s mod lists.'],
])
entry('class:ModMetadata', 'Informations destinées aux listes et fiches de mods du jeu. name et description acceptent tr ; les métadonnées de distribution du Hub ou de Steam restent séparées.', 'Information for the game’s mod lists and details. name and description accept tr; Hub or Steam distribution metadata remains separate.')
properties('ModMetadata', [
  ['author', 'Signature de l’auteur affichée dans les informations du mod ; ce texte ne définit ni identité de service ni règle.', 'Author credit shown in mod information; this text defines neither a service identity nor a rule.'],
  ['description', 'Description affichée du mod ; accepte tr et des retours à la ligne. Le paquet conserve un texte de repli lisible.', 'Displayed mod description; accepts tr and line breaks. The package retains readable fallback text.'],
  ['name', 'Nom optionnel pour les listes et fiches de mods du jeu, éventuellement traduit. null reprend le nom de mod.json. Ne remplace pas GameMod.title dans le groupe Options → NRF Hub, ni ToolWindow.title ; identifiant et version restent inchangés.', 'Optional name for the game’s mod lists and details, possibly translated. null uses the name from mod.json. Does not replace GameMod.title in the Options → NRF Hub group or ToolWindow.title; identifier and version remain unchanged.'],
])
entry('class:SignalConstruction', 'Déclaration du catalogue d’images et du signal constructible. Les chemins sont relatifs au paquet et vérifiés lors de sa génération. Conservez l’ordre publié pour les sauvegardes.', 'Declares the image catalogue and constructible signal. Paths are package-relative and checked during generation. Preserve published order for existing saves.')
properties('SignalConstruction', [
  ['name', 'Nom dans le menu de construction ; accepte un texte ou tr. Distinct de l’identifiant du modèle.', 'Name in the construction menu; accepts plain text or tr. Separate from the model identifier.'],
  ['kind', 'Type de signal reconnu par le jeu ; path par défaut. Une valeur syntaxiquement valide ne garantit pas qu’un autre type soit pris en charge.', 'Signal kind recognized by the game; defaults to path. A syntactically valid value does not guarantee support for another kind.'],
  ['catalogueName', 'Nom affiché du jeu de textures, égal à name par défaut ; accepte tr.', 'Displayed texture-set name, equal to name by default; accepts tr.'],
  ['nameKey', 'Clé de localisation native pour un catalogue existant. null avec name=tr(...), car ces deux mécanismes ne se combinent pas pour le même nom.', 'Native localization key for an existing catalogue. Leave null with name=tr(...), as these mechanisms cannot be combined for the same name.'],
  ['catalogueNameKey', 'Clé de localisation native du catalogue. Laissez null lorsque catalogueName utilise tr ; ce n’est pas une clé du JSON de traductions du mod.', 'Native catalogue localization key. Leave null when catalogueName uses tr; this is not a key in the mod’s translation JSON.'],
  ['size', 'Taille par défaut du signal à construire, de 0 à 4 ; 0 par défaut. Déclarez 4 explicitement pour choisir cette taille.', 'Default size of the signal to build, from 0 to 4; defaults to 0. Explicitly declare 4 to select that size.'],
  ['left', 'Choix initial du côté gauche lors de la construction. false par défaut ; définir true si le modèle doit être placé à gauche.', 'Initial left-side choice when building. Defaults to false; set true when the model should be placed on the left.'],
  ['states', 'Copie de 1 à 256 chemins distincts, dans leur ordre définitif. Déclarez chaque image fixe et les deux images de tout clignotement.', 'Copy of 1 to 256 distinct paths in their permanent order. Declare every steady image and both images of every blink.'],
])
entry('fun:signalMod(ModInfo,SignalModelsBuilder.()->Unit)', 'Assemble des modèles indépendants avec l’identité générée depuis mod.json. À renvoyer depuis createMod ; la déclaration doit rester sans accès au jeu.', 'Assembles independent models with the identity generated from mod.json. Return it from createMod; declaration must remain free of game access.')
entry('fun:toolMod(ModInfo,ToolModBuilder.()->Unit)', 'Assemble un outil avec l’identité générée depuis mod.json, sans signal fictif. Déclarez au moins un service ou une fenêtre.', 'Assembles a tool with the identity generated from mod.json, without a fictitious signal. Declare at least one service or window.')

related = ['/mods/outils-optionnels', '/mods/interface', '/mods/cycle-outils']
entry('class:SignalAction', 'Bouton facultatif d’un signal, relié à un service de mod outil. Le fournisseur absent masque le bouton sans supprimer le signal ni changer ses règles.', 'Optional signal button connected to a tool-mod service. An absent provider hides the button without removing the signal or changing its rules.')
properties('SignalAction', [
  ['id', 'Identifiant stable de l’action, unique parmi les actions du modèle. Transmis au service lors du clic.', 'Stable action identifier, unique among the model’s actions. Sent to the service on click.'],
  ['label', 'Texte du bouton dans le panneau de signal ; accepte tr et reste distinct de id.', 'Button text in the signal panel; accepts tr and remains separate from id.'],
  ['whenMod', 'Identifiant technique du mod fournisseur. Sert à la disponibilité du bouton, sans imposer son installation.', 'Technical identifier of the provider mod. Controls button availability without requiring its installation.'],
  ['service', 'Identifiant exact du service déclaré par le fournisseur avec service(...). Il ne s’agit pas d’un nom de fonction Kotlin.', 'Exact service identifier declared by the provider through service(...). It is not a Kotlin function name.'],
])
entry('class:SignalActionRequest', 'Événement fourni au service après une action sur un signal. Conservez ses informations de session et de panneau pour répondre ; un clic ne valide pas à lui seul un plan de construction.', 'Event supplied to the service after a signal action. Retain its session and panel information when responding; a click alone does not validate a construction plan.')
properties('SignalActionRequest', [
  ['sequence', 'Numéro de l’événement reçu. Utilisez la requête fournie pour rattacher votre réponse à cette action, sans fabriquer une nouvelle séquence.', 'Number of the received event. Use the supplied request to associate your response with this action; do not fabricate a sequence.'],
  ['signalId', 'Signal source sélectionné. Il peut être supprimé ou modifié ensuite ; revalidez avant une mutation.', 'Selected source signal. It can later be deleted or changed; revalidate before a mutation.'],
  ['action', 'Identifiant du bouton ou du champ modifié dans le panneau. Le service doit sélectionner explicitement le traitement correspondant.', 'Identifier of the activated button or edited field in the panel. The service must explicitly select the corresponding action.'],
  ['service', 'Service destinataire déclaré par le mod outil. Les événements suivants du même panneau reviennent à ce service.', 'Target service declared by the tool mod. Subsequent events from the same panel return to this service.'],
  ['worldId', 'Identité de la partie ayant produit l’événement. Une requête d’un autre monde ne peut pas présenter ou confirmer le plan courant.', 'Identity of the game world that produced the event. A request from another world cannot present or confirm the current plan.'],
  ['generation', 'Génération de session à comparer avec le contexte actuel. Invalidez plan et aperçu lors d’un changement.', 'Session generation to compare with the current context. Invalidate plan and preview when it changes.'],
  ['panelToken', 'Identité opaque du panneau d’origine. Transmettez la requête reçue aux méthodes de présentation plutôt que de reconstruire ce jeton.', 'Opaque identity of the originating panel. Pass the received request to presentation methods instead of reconstructing this token.'],
  ['originAction', 'Action initiale qui a ouvert le panneau, conservée lorsque action devient un bouton ou un champ de ce panneau.', 'Initial action that opened the panel, preserved when action becomes one of that panel’s buttons or fields.'],
  ['value', 'Nouvel entier validé d’un champ numérique ; null pour un bouton. Une saisie vide ou invalide n’est pas remplacée par zéro.', 'New validated integer from a numeric field; null for a button. Empty or invalid input is not replaced with zero.'],
])
entry('class:GameMod', 'Base commune des mods de signalisation et d’outils. createMod renvoie une implémentation déclarée par le DSL ; un outil n’a pas besoin de modèle de signal.', 'Common base for signalling and tool mods. createMod returns a DSL-declared implementation; a tool does not need a signal model.')
entry('class:ToolMod', 'Mod outil construit par toolMod. Ses services et fenêtres reçoivent des événements sans définir d’aspect ni de consigne de signalisation ; constructeur réservé au SDK.', 'Tool mod constructed through toolMod. Its services and windows receive events without defining signalling aspects or rules; construction is reserved for the SDK.')
for (const owner of ['GameMod', 'ToolMod']) {
  properties(owner, [
    ['id', 'Identifiant stable du mod, utilisé par whenMod pour joindre ses services. Réutilisez modInfo.id plutôt qu’un libellé traduit.', 'Stable mod identifier, used by whenMod to reach its services. Reuse modInfo.id rather than a translated label.'],
    ['title', 'Titre déclaré du mod, utilisé pour regrouper ses préférences et raccourcis dans Options → NRF Hub. Vient de modInfo.title avec la surcharge modInfo ; metadata(name=...) ne remplace pas ce titre. L’identité reste id.', 'Declared mod title, used to group its preferences and shortcuts in Options → NRF Hub. Comes from modInfo.title with the modInfo overload; metadata(name=...) does not replace it. Identity remains id.'],
    ['metadata', 'Informations de présentation déclarées avec metadata ; null si aucune n’est fournie. Ne décrit pas les règles de l’outil.', 'Presentation information declared through metadata; null when none is supplied. Does not describe tool rules.'],
    ['windows', 'Fenêtres déclarées par le mod. Liste vide si aucune ; leur création n’exige pas de signal sélectionné.', 'Windows declared by the mod. Empty when none are declared; opening them requires no selected signal.'],
    ['services', 'Identifiants des services enregistrés par le mod. Les actions externes doivent utiliser exactement ces identifiants.', 'Identifiers of services registered by the mod. External actions must use these exact identifiers.'],
  ])
  entry(`fun:${owner}.onWindowEvent(ToolWindowEvent,ToolContext)`, 'Traite un événement de fenêtre avec un contexte valable uniquement pendant cet appel. Le DSL dirige l’événement vers le handler de request.window.', 'Handles a window event with a context valid only during this call. The DSL routes the event to the handler for request.window.')
  entry(`fun:${owner}.onSignalAction(SignalActionRequest,ToolContext)`, 'Traite une action de signal dans le service destinataire. Gardez le callback court, validez la session et ne conservez pas ToolContext après le retour.', 'Handles a signal action in its target service. Keep the callback short, validate the session and do not retain ToolContext after returning.')
  entry(`fun:${owner}.onTick(ToolContext)`, 'Callback périodique pour avancer un travail borné, renouveler une présentation ou suivre un ticket. Il ne garantit pas une fréquence exacte ; retournez sans attendre.', 'Periodic callback to advance bounded work, renew presentation or poll a ticket. It does not guarantee an exact frequency; return without waiting.')
  entry(`fun:${owner}.onStop()`, 'Libère l’état local et les ressources lors d’un arrêt normal du mod. Aucun ToolContext n’est fourni ; ne comptez pas sur ce callback après un arrêt brutal.', 'Releases local state and resources during a normal mod shutdown. No ToolContext is supplied; do not rely on this callback after an abrupt termination.')
}
entry('class:ToolModBuilder', 'Configuration reçue dans toolMod : services, fenêtres, métadonnées et callbacks de cycle de vie. Le SDK crée ce builder ; ne l’instanciez pas directement.', 'Configuration received inside toolMod: services, windows, metadata and lifecycle callbacks. The SDK creates this builder; do not instantiate it directly.')
entry('fun:ToolModBuilder.window(String,String,String,ToolContext.(ToolWindowEvent)->Unit)', 'Enregistre une fenêtre autonome et son handler, jusqu’à 8 identifiants distincts. Le SDK crée son option de raccourci, modifiable par le joueur : F8 par défaut, vide pour désactiver. Format : Ctrl+, Alt+, Shift+ facultatifs dans cet ordre puis A–Z, 0–9, F1–F24 ou une touche nommée du guide. Les raccourcis non vides du mod doivent être distincts. showWindow fournit le contenu.', 'Registers a standalone window and handler, up to 8 distinct IDs. The SDK creates its player-configurable shortcut option: F8 by default, empty to disable. Format: optional Ctrl+, Alt+, Shift+ in that order followed by A–Z, 0–9, F1–F24 or a named key from the guide. Nonempty shortcuts within the mod must be distinct. showWindow supplies the content.')
entry('fun:ToolModBuilder.metadata(String,String,String?)', 'Déclare auteur, description et nom optionnel pour les listes et fiches de mods du jeu. name et description acceptent tr. Ne remplace ni le titre du groupe dans Options → NRF Hub, ni les titres de fenêtres ; l’identité vient de mod.json.', 'Declares the author, description and optional name for the game’s mod lists and details. name and description accept tr. Replaces neither the group heading in Options → NRF Hub nor window titles; identity comes from mod.json.')
entry('fun:ToolModBuilder.service(String,ToolContext.(SignalActionRequest)->Unit)', 'Enregistre un service avec identifiant unique, jusqu’à 32 par mod. Les callbacks d’un mod sont sérialisés ; un handler bloquant retarde les autres tâches de ce même mod.', 'Registers a service with a unique identifier, up to 32 per mod. A mod’s callbacks are serialized; a blocking handler delays that same mod’s other tasks.')
entry('fun:ToolModBuilder.onTick(ToolContext.()->Unit)', 'Déclare le travail périodique de l’outil. Traitez seulement les tâches en attente et rendez la main ; évitez lecture complète du réseau et attente à chaque tick.', 'Declares periodic tool work. Process only pending tasks and return; avoid a full network read and waiting on every tick.')
entry('fun:ToolModBuilder.onStop(()->Unit)', 'Déclare le nettoyage local à l’arrêt normal. Ne conserve ni n’utilise un contexte d’un callback précédent.', 'Declares local cleanup during normal shutdown. Must not retain or use a context from an earlier callback.')
entry('fun:toolMod(String,String,ToolModBuilder.()->Unit)', 'Construit un outil avec identité explicite et au moins un service ou une fenêtre. Dans un projet Gradle, préférez toolMod(modInfo) pour utiliser l’identité générée.', 'Builds a tool with an explicit identity and at least one service or window. In a Gradle project, prefer toolMod(modInfo) to use the generated identity.')

related = ['/mods/reglages', '/mods/interface']
entry('class:NumberSetting', 'Réglage entier persistant de signal, compris entre zéro et maximum. Déclarez number(option) dans le modèle ; lisez avec read et préparez des copies avec withValue.', 'Persistent integer signal setting from zero through maximum. Declare number(option) in the model; read it with read and prepare copies with withValue.')
properties('NumberSetting', [
  ['name', 'Clé stable de 1 à 96 caractères, commençant par une lettre ASCII, puis lettres, chiffres, point, tiret ou soulignement. Ne pas traduire.', 'Stable key of 1 to 96 characters, starting with an ASCII letter, followed by letters, digits, dots, hyphens or underscores. Do not translate.'],
  ['label', 'Libellé du champ dans le panneau du signal ; accepte tr. Ne détermine pas le sens métier de la valeur.', 'Field label in the signal panel; accepts tr. Does not define the value’s domain meaning.'],
  ['maximum', 'Borne supérieure incluse, de 1 à 65535. La borne inférieure des valeurs est toujours zéro.', 'Inclusive upper bound, from 1 to 65535. The lower value bound is always zero.'],
  ['defaultValue', 'Valeur par défaut comprise entre zéro et maximum ; zéro par défaut. Les valeurs manquantes sont complétées par ce défaut à la lecture.', 'Default value between zero and maximum; defaults to zero. Missing values use this default when read.'],
  ['visibleWhen', 'Nom d’une case du même modèle qui contrôle la visibilité ; chaîne vide pour toujours afficher. Masquer le champ n’efface pas sa valeur.', 'Name of a checkbox in the same model controlling visibility; empty for always visible. Hiding the field does not erase its value.'],
])
entry('fun:NumberSetting.read(Map<String,Boolean>)', 'Lit l’entier dans une carte de réglages, complète les données manquantes par le défaut et borne le résultat entre zéro et maximum. Aucun accès au jeu.', 'Reads the integer from a settings map, fills missing data from its default and clamps the result between zero and maximum. No game access occurs.')
entry('fun:NumberSetting.withValue(Map<String,Boolean>,Int)', 'Retourne une nouvelle carte avec l’entier demandé en conservant les autres réglages. Refuse une valeur hors de 0..maximum ; ce calcul ne sauvegarde rien dans la partie.', 'Returns a new map with the requested integer while preserving other settings. Rejects values outside 0..maximum; this calculation saves nothing into the game.')

