entry('class:ToolButton', 'Bouton temporaire d’un panneau ou d’une fenêtre. Son libellé n’exécute aucune action ; le handler traite l’identifiant reçu. Sa suppression ne modifie pas les réglages persistants des signaux.', 'Temporary button in a panel or window. Its label performs no action; the handler processes the received identifier. Removing it does not alter persistent signal settings.')
properties('ToolButton', [
  ['id', 'Identifiant technique transmis dans action au clic, distinct des autres boutons et champs du formulaire.', 'Technical identifier sent as action on click, distinct from other buttons and fields in the form.'],
  ['label', 'Texte affiché sur le bouton ; accepte tr. Gardez id stable lorsque ce texte change.', 'Text shown on the button; accepts tr. Keep id stable when this text changes.'],
  ['enabled', 'false désactive le bouton dans le formulaire publié. Le handler doit aussi revalider l’état local avant toute mutation.', 'false disables the button in the published form. The handler must also revalidate local state before any mutation.'],
])
entry('class:ToolNumberInput', 'Champ entier temporaire avec valeur et bornes explicites. Un panneau envoie chaque édition valide dans request.value ; une fenêtre envoie tous les champs au clic. Un brouillon invalide bloque les commandes.', 'Temporary integer field with explicit value and bounds. A panel sends each valid edit in request.value; a window sends all fields on click. An invalid draft blocks commands.')
properties('ToolNumberInput', [
  ['id', 'Clé du champ dans action ou ToolWindowEvent.values, distincte des autres contrôles du formulaire.', 'Field key in action or ToolWindowEvent.values, distinct from other controls in the form.'],
  ['label', 'Libellé du champ entier, affiché avec la saisie ; accepte tr.', 'Integer-field label shown with the input; accepts tr.'],
  ['value', 'Entier proposé lors de la publication du formulaire. Doit appartenir à minimum..maximum ; une republication doit respecter le brouillon validé de l’outil.', 'Integer proposed when publishing the form. Must lie within minimum..maximum; republishing should respect the tool’s validated draft.'],
  ['minimum', 'Borne inférieure incluse de la saisie. Doit être inférieure ou égale à maximum.', 'Inclusive lower input bound. Must not exceed maximum.'],
  ['maximum', 'Borne supérieure incluse de la saisie ; la valeur publiée et les éditions acceptées doivent la respecter.', 'Inclusive upper input bound; both the published value and accepted edits must respect it.'],
  ['enabled', 'false rend la saisie non modifiable dans ce formulaire ; ne supprime pas la valeur de l’état local de l’outil.', 'false makes the input noneditable in this form; does not remove the value from the tool’s local state.'],
])
