entry('class:LogLevel', 'Niveau de gravité d’un message écrit par ToolContext.log. Choisissez le niveau selon le résultat métier et évitez de répéter un message à chaque tick.', 'Severity of a message written through ToolContext.log. Choose it according to the domain outcome and avoid repeating a message on every tick.')
entry('enum-entry:LogLevel.Info', 'Événement de fonctionnement normal, par exemple une opération terminée ou un changement de phase.', 'Normal operation event, such as an operation completing or a phase changing.')
entry('enum-entry:LogLevel.Warning', 'Situation inhabituelle dont l’outil peut rendre compte sans la classer comme une erreur définitive.', 'Unusual situation that the tool can report without classifying it as a permanent error.')
entry('enum-entry:LogLevel.Error', 'Échec à diagnostiquer. Gardez le message utile et borné ; écrire un journal peut lui-même être temporairement refusé.', 'Failure requiring diagnosis. Keep the message useful and bounded; writing a log can itself be temporarily refused.')
related = ['/mods/cycle-outils', '/mods/parcours-voies', '/mods/horloge']
entry('class:ToolContext', 'Accès au jeu fourni uniquement pendant un callback de l’outil. Ne conservez ni ce contexte ni une fermeture qui le capture. Les valeurs copiées, identifiants de session et tickets peuvent être conservés pour le callback suivant.', 'Game access supplied only during a tool callback. Retain neither this context nor a closure capturing it. Copied values, session identifiers and tickets may be kept for the next callback.')
properties('ToolContext', [
  ['worldId', 'Identité de la partie active pour cet appel. Comparez-la à celle du plan ou de l’événement avant de réutiliser des données.', 'Identity of the active game world for this call. Compare it with the plan or event before reusing data.'],
  ['generation', 'Génération de session active pour cet appel. Un changement invalide les plans et les présentations de l’ancienne génération.', 'Active session generation for this call. A change invalidates plans and presentations from the old generation.'],
])
entry('fun:ToolContext.log(String,LogLevel)', 'Écrit un message persistant de 1 à 4096 octets UTF-8, sans caractère nul. Ne pas journaliser de secrets ni chaque tick ; traiter un éventuel refus sans boucle de diagnostics.', 'Writes a persistent message of 1 to 4096 UTF-8 bytes without NUL characters. Do not log secrets or every tick; handle a possible refusal without a diagnostic loop.')
entry('fun:ToolContext.clock()', 'Lit uniquement calendrier et temps simulé, sans capturer le réseau. Utilisez cette lecture légère pour un affichage d’heure ; le résultat copié ne se met pas à jour tout seul.', 'Reads only calendar and simulation time, without capturing the network. Use this lightweight read for clock displays; the copied result does not update itself.')
entry('fun:ToolContext.trains(TrainQuery)', 'Lit les groupes de données demandés pour les trains. Réutilise une lecture du même callback si elle couvre la requête ; un besoin supplémentaire déclenche une lecture élargie. Les copies restent lisibles après le callback.', 'Reads the requested train-data groups. Reuses a read from the same callback when it covers the query; additional requirements trigger an expanded read. Copies remain readable after the callback.')
entry('fun:ToolContext.linePlan(Long)', 'Lit le plan complet de la ligne du train identifié, ou null si absent/instable. Les horaires sont des offsets, pas des dates commerciales absolues. Réutilisé dans le callback ; network renouvelle la lecture.', 'Reads the identified train’s complete line plan, or null if absent/unstable. Timetable values are offsets, not absolute service dates. Reused within the callback; network refreshes the read.')
entry('fun:ToolContext.linePlan(TrainId)', 'Même lecture de plan avec un identifiant de train typé. Retourne LinePlan ou null lorsque le plan est absent/instable ; ne déduit pas la date d’une circulation.', 'The same plan read with a typed train identifier. Returns LinePlan or null when absent/unstable; does not infer a service run’s date.')
entry('fun:ToolContext.changeTime(Long,Boolean)', 'Change le calendrier UTC, années 1 à 9999, en conservant la fraction de seconde. Par défaut, conserve positions et délais relatifs. recalculateTrains peut déplacer des trains et coûter de l’argent : choix explicite requis. Après erreur incertaine, relire plutôt que rejouer.', 'Changes the UTC calendar within years 1 to 9999, preserving the fractional second. Preserves positions and relative deadlines by default. recalculateTrains may move trains and cost money: require an explicit choice. After an uncertain error, read back instead of replaying.')
entry('fun:ToolContext.changeTime(GameDateTime,Boolean)', 'Convertit la date validée en secondes UTC puis applique changeTime. Même mutation et même nécessité de relire après un résultat incertain ; calculer la date seul ne changeait pas la partie.', 'Converts the validated date to UTC seconds and applies changeTime. The same mutation and read-back requirement after an uncertain outcome apply; calculating the date alone did not change the game.')
entry('fun:ToolContext.showWindow(ToolWindowEvent,String,List<ToolButton>,List<ToolNumberInput>)', 'Publie le formulaire de la fenêtre ayant produit l’événement, dans la même session : jusqu’à 12 boutons et 8 entiers, IDs distincts. Valeurs envoyées ensemble au clic ; 4096 octets UTF-8 par chaîne sans caractère nul, et 8192 au total.', 'Publishes the form for the window that produced the event, in the same session: up to 12 buttons and 8 integers, with distinct IDs. Values are sent together on click; 4096 UTF-8 bytes per string without NUL characters, and 8192 in total.')
entry('fun:ToolContext.network()', 'Capture une nouvelle copie de voies, aiguilles et signaux ; invalide les lectures de trains réutilisées dans ce contexte sans les relire immédiatement. À appeler après prepareConstruction pour calculer le plan à confirmer, pas à chaque renouvellement d’aperçu.', 'Captures a fresh copy of tracks, junctions and signals; invalidates train reads reused within this context without immediately rereading them. Call after prepareConstruction to compute the plan to confirm, not for every preview renewal.')
entry('fun:ToolContext.prepareConstruction(Long)', 'Prépare un ticket pour copier le signal source, sans poser de signal. Faire ensuite une nouvelle capture et valider les positions. Une commande d’édition ou un changement de session peut invalider ce ticket.', 'Prepares a ticket to copy the source signal without building a signal. Then take a fresh capture and validate positions. An editor command or session change may invalidate the ticket.')
entry('fun:ToolContext.showSignalPreview(SignalActionRequest,List<SignalPosition>)', 'Publie jusqu’à 64 positions avec le modèle source, sans construction. Renouveler pendant l’usage : expiration après deux secondes. Visible pendant l’édition de la source ; couches et cadrage restent applicables. Un refus Busy ne renouvelle pas l’ancien aperçu et interdit une confirmation locale.', 'Publishes up to 64 positions with the source kind, without construction. Renew while in use: it expires after two seconds. Visible while editing the source; layers and framing still apply. A Busy refusal does not renew the old preview and must prevent local confirmation.')
entry('fun:ToolContext.clearSignalPreview()', 'Demande le retrait de l’aperçu de l’outil, sans annuler une construction. En cas de Busy, révoquez immédiatement la confirmation locale puis retentez le nettoyage dans un callback ultérieur.', 'Requests removal of the tool’s preview without undoing construction. On Busy, immediately revoke local confirmation and retry cleanup in a later callback.')
entry('fun:ToolContext.createSignals(Long,Long,List<SignalPosition>)', 'Soumet une seule fois 1 à 64 positions distinctes avec ticket préparé et signal source. Validez une nouvelle capture contre le plan approuvé avant l’appel. Pending ou erreur incertaine impose de suivre le même ticket, jamais de rejouer la pose.', 'Submits 1 to 64 distinct positions once with a prepared ticket and source signal. Validate a fresh capture against the approved plan before calling. Pending or an uncertain error requires tracking that same ticket, never replaying construction.')
entry('fun:ToolContext.undoConstruction(Long)', 'Demande explicitement l’annulation du ticket lorsque canUndo le permet. L’historique peut avoir changé ; un refus reste possible. Marquez l’opération en attente avant l’appel et suivez son résultat sans la répéter.', 'Explicitly requests undo for the ticket when canUndo allows it. History may have changed, so rejection remains possible. Mark the operation pending before calling and track its result without repeating it.')
entry('fun:ToolContext.pollConstruction(Long)', 'Interroge le ticket non nul original sans resoumettre la commande. Continuez pendant Pending, même si le panneau est fermé. Un ticket devenu indisponible ne prouve pas une absence d’effet.', 'Polls the original nonzero ticket without resubmitting the command. Continue during Pending, even if the panel is closed. A ticket becoming unavailable does not prove there were no effects.')
entry('fun:ToolContext.showPanel(SignalActionRequest,String,List<ToolButton>,List<ToolNumberInput>)', 'Remplace l’action d’origine par un panneau temporaire : jusqu’à 12 boutons et 4 entiers, IDs distincts. Chaque chaîne doit respecter 256 caractères et 256 octets UTF-8, sans caractère nul. Utilisez la requête de la même session. Un refus de présentation ne valide pas les anciens clics ; les réglages persistants du signal ne sont pas modifiés.', 'Replaces the originating action with a temporary panel: up to 12 buttons and 4 integers, with distinct IDs. Each string must fit both 256 characters and 256 UTF-8 bytes, without NUL characters. Use the request from the same session. A presentation refusal does not validate old clicks; persistent signal settings remain unchanged.')
entry('class:ToolOperationException', 'Refus typé d’une opération d’outil. Distinguez isBusy des erreurs permanentes ; après une mutation incertaine, inspectez le résultat plutôt que de répéter la commande.', 'Typed refusal of a tool operation. Distinguish isBusy from permanent errors; after an uncertain mutation, inspect the outcome instead of repeating the command.')
properties('ToolOperationException', [
  ['status', 'Code de statut SDK conservé pour le diagnostic. Utilisez isBusy pour le cas temporaire connu, sans classer toutes les erreurs comme temporaires.', 'SDK status code retained for diagnosis. Use isBusy for the known temporary case without treating all errors as temporary.'],
  ['isBusy', 'true pour le refus temporaire de statut 12. Une lecture ou présentation peut attendre un prochain callback ; une écriture incertaine ne doit pas être automatiquement rejouée.', 'true for temporary status-12 refusal. A read or presentation may wait for a later callback; an uncertain write must not be replayed automatically.'],
])

related = ['/mods/parcours-voies']
entry('class:ToolTrackEnd', 'Extrémité géométrique d’une voie, indépendante de la direction actuelle d’un train.', 'Geometric end of a track, independent of a train’s current direction.')
entry('enum-entry:ToolTrackEnd.A', 'Origine géométrique : fraction zéro et distance zéro. Un parcours entrant par A continue vers B.', 'Geometric origin: fraction zero and distance zero. A traversal entering at A continues towards B.')
entry('enum-entry:ToolTrackEnd.B', 'Autre extrémité : fraction un et distance égale à la longueur. Un parcours entrant par B continue vers A.', 'Other end: fraction one and distance equal to the length. A traversal entering at B continues towards A.')
entry('interface:ToolTrackConnection', 'Résultat typé d’un raccordement observé : Join exploitable, Junction à traiter explicitement ou Unknown. Ne choisit aucune branche d’aiguille.', 'Typed observed-connection result: usable Join, explicitly handled Junction, or Unknown. Selects no junction branch.')
entry('object:ToolTrackConnection.Unknown', 'Raccord insuffisamment connu, absent, ambigu ou vers une voie sans longueur exploitable. Ne signifie pas fin de voie ; arrêtez le parcours.', 'Insufficiently known, absent or ambiguous connection, or one leading to a track without usable length. Does not mean a dead end; stop traversal.')
entry('object:ToolTrackConnection.Junction', 'Une aiguille occupe cette extrémité. Le SDK ne sélectionne pas de branche ; votre outil doit refuser ou appliquer une politique de route explicite.', 'A junction occupies this end. The SDK does not select a branch; your tool must stop or apply an explicit routing policy.')
entry('class:ToolTrackConnection.Join', 'Raccord réciproque vers une voie connue avec longueur exploitable. entry identifie l’extrémité d’arrivée sur cette autre voie.', 'Reciprocal connection to a known track with usable length. entry identifies the arrival end on that other track.')
properties('ToolTrackConnection.Join', [
  ['trackId', 'Identifiant de la voie suivante dans cette topologie, à résoudre avec track(trackId).', 'Identifier of the next track in this topology, resolved with track(trackId).'],
  ['entry', 'Extrémité par laquelle le parcours entre sur la voie suivante. A implique un parcours vers B, et inversement.', 'End through which traversal enters the next track. A implies movement towards B, and conversely.'],
])
entry('class:ToolRouteTrack', 'Vue de voie exploitable pour un calcul de distance : longueur connue, raccords typés et positions d’aiguilles. Les aiguilles intérieures doivent aussi être contrôlées.', 'Track view usable for distance calculation: known length, typed connections and junction positions. Interior junctions must also be checked.')
properties('ToolRouteTrack', [
  ['id', 'Identifiant stable dans la copie de topologie ; ne vaut pas autorisation de poser dans l’état actuel du monde.', 'Identifier stable within the topology copy; does not authorize building in the world’s current state.'],
  ['lengthM', 'Longueur finie strictement positive, en mètres ; les voies sans longueur connue sont exclues de cette vue.', 'Finite, strictly positive length in metres; tracks without known length are excluded from this view.'],
  ['a', 'Raccordement typé à l’extrémité A ; consulter aussi junctionOffsetsM avant d’atteindre cette extrémité.', 'Typed connection at end A; also inspect junctionOffsetsM before reaching that end.'],
  ['b', 'Raccordement typé à l’extrémité B ; aucune branche n’est choisie implicitement.', 'Typed connection at end B; no branch is selected implicitly.'],
  ['junctionOffsetsM', 'Positions d’aiguilles triées, en mètres depuis A, y compris les raccords abordés en talon. Une liste vide concerne cette copie seulement.', 'Sorted junction positions in metres from A, including trailing connections. An empty list describes this copy only.'],
])
entry('fun:ToolRouteTrack.connection(ToolTrackEnd)', 'Retourne a ou b selon l’extrémité demandée, sans relire le réseau et sans choisir de branche.', 'Returns a or b for the requested end without rereading the network or selecting a branch.')
entry('class:ToolTopology', 'Copie indexée obtenue par ToolNetwork.topology. Omet voies sans longueur connue et leurs signaux, laissant les raccords inconnus. Réutilisez-la pour le calcul puis relisez avant une mutation ; constructeur réservé au SDK.', 'Indexed copy obtained through ToolNetwork.topology. Omits tracks without known length and their signals, leaving connections unknown. Reuse it for calculation, then reread before mutation; construction is reserved for the SDK.')
properties('ToolTopology', [
  ['worldId', 'Identité de la partie de la copie d’origine. À comparer au contexte avant toute réutilisation d’un plan.', 'World identity of the original copy. Compare it with the context before reusing a plan.'],
  ['generation', 'Génération de session de la topologie, conservée depuis ToolNetwork.', 'Topology session generation, retained from ToolNetwork.'],
  ['tracks', 'Voies de longueur connue avec connexions typées. Pour un parcours court, préférez track(id) à une nouvelle recherche dans toute la liste.', 'Known-length tracks with typed connections. For a short route, prefer track(id) to repeatedly searching the entire list.'],
  ['signals', 'Signaux rattachés aux voies exploitables de cette topologie ; ceux des voies omises ne sont pas conservés ici.', 'Signals attached to usable tracks in this topology; those on omitted tracks are not retained here.'],
])
entry('fun:ToolTopology.track(Long)', 'Recherche une voie par identifiant dans la copie ; null si absente ou sans longueur connue. Ne déclenche aucune lecture de la partie.', 'Looks up a track by ID in the copy; null if absent or without known length. Triggers no game read.')
entry('fun:ToolTopology.signal(Long)', 'Recherche un signal conservé dans la copie ; null s’il est absent ou rattaché à une voie omise. Ne prouve pas qu’il a été supprimé en jeu.', 'Looks up a retained signal in the copy; null if absent or attached to an omitted track. Does not prove in-game deletion.')
entry('fun:ToolNetwork.topology()', 'Valide la copie et prépare ses recherches de distances, aiguilles et raccordements. Refuse identités dupliquées, longueurs, fractions ou directions invalides. Les liens absents ou ambigus deviennent Unknown ; aucune capture supplémentaire.', 'Validates the copy and prepares distance, junction and connection lookups. Rejects duplicate identities and invalid lengths, fractions or directions. Absent or ambiguous links become Unknown; takes no additional capture.')

related = ['/mods/horloge', '/mods/interface']
entry('class:ToolWindow', 'Déclaration d’une fenêtre autonome d’outil, accessible par raccourci pendant le jeu. Enregistrez-la avec ToolModBuilder.window ; aucun signal sélectionné n’est nécessaire.', 'Standalone tool-window declaration, accessible by shortcut while playing. Register it through ToolModBuilder.window; no selected signal is required.')
properties('ToolWindow', [
  ['id', 'Identifiant de fenêtre unique dans le mod, reçu dans ToolWindowEvent.window. Gardez-le stable entre versions : la préférence du raccourci lui est rattachée. Ne pas traduire cet identifiant.', 'Window identifier unique within the mod, received in ToolWindowEvent.window. Keep it stable across versions: the shortcut preference is attached to it. Do not translate this identifier.'],
  ['title', 'Texte utilisé à la fois comme titre de fenêtre et comme libellé de son raccourci sous le groupe du mod dans Options → NRF Hub. Accepte tr ; un titre court évite de répéter le nom du mod. Le modifier ne change pas l’identité.', 'Text used both as the window title and its shortcut label under the mod’s group in Options → NRF Hub. Accepts tr; a short title avoids repeating the mod name. Changing it does not change identity.'],
  ['shortcut', 'Raccourci initial au format accepté par window(...) ; vide pour désactiver. Le joueur peut modifier l’affectation dans les options du SDK. La déclaration ne représente pas forcément son affectation actuelle.', 'Initial shortcut in the format accepted by window(...); empty to disable. The player can change the binding in the SDK options. The declaration does not necessarily represent the current binding.'],
])
entry('class:ToolWindowEvent', 'Événement fourni au handler de fenêtre. Les champs valides sont transmis ensemble au clic, pas à chaque touche. Utilisez la même requête pour publier le formulaire correspondant.', 'Event supplied to a window handler. Valid fields are sent together on click, not on each keystroke. Use the same request to publish its corresponding form.')
properties('ToolWindowEvent', [
  ['window', 'Identifiant de la fenêtre déclarée ayant produit cet événement.', 'Identifier of the declared window that produced this event.'],
  ['action', 'open à l’ouverture, puis identifiant du bouton activé. Le texte du bouton ne définit pas son traitement.', 'open when opening, then the identifier of the activated button. Button text does not define its handling.'],
  ['values', 'Carte des entiers validés du formulaire au moment du clic, indexée par identifiant de champ. Un champ absent ne doit pas être inventé à zéro.', 'Map of validated form integers at click time, keyed by field ID. An absent field must not be invented as zero.'],
  ['sequence', 'Séquence du formulaire/événement fourni par le SDK. Transmettez-la via la requête reçue ; ne fabriquez pas un événement pour réutiliser une ancienne fenêtre.', 'Form/event sequence supplied by the SDK. Pass it through the received request; do not fabricate an event to reuse an old window.'],
  ['worldId', 'Identité de partie de l’événement, exigée identique à celle de ToolContext pour showWindow.', 'Event world identity, required to match ToolContext for showWindow.'],
  ['generation', 'Génération de session de l’événement. Une autre génération impose de rejeter l’ancien formulaire et ses intentions.', 'Event session generation. A different generation requires rejecting the old form and its intentions.'],
])
entry('class:ToolClock', 'Lecture copiée de deux temps distincts : calendrier UTC et durée simulée écoulée. La pause, l’accélération et une modification de date ne doivent pas être confondues avec le temps réel du PC.', 'Copied reading of two different times: UTC calendar and elapsed simulation time. Pause, acceleration and a date change must not be confused with the computer’s real time.')
properties('ToolClock', [
  ['utcSeconds', 'Calendrier de la partie en secondes signées depuis le 1er janvier 1970 UTC. Convertir avec dateTime ; ce n’est pas l’heure système du PC.', 'Game calendar in signed seconds since 1 January 1970 UTC. Convert with dateTime; this is not the computer’s system clock.'],
  ['elapsedMillis', 'Temps de simulation écoulé en millisecondes. Utilisez cette unité pour raisonner sur la simulation, sans l’interpréter comme une date UTC.', 'Elapsed simulation time in milliseconds. Use this unit to reason about simulation without interpreting it as a UTC date.'],
])
entry('class:ToolTimeChange', 'Résultat d’un changement de calendrier : horloge retournée et nombre d’interventions de recalcul. Une réponse reçue permet d’afficher l’état obtenu, sans rejouer la commande.', 'Result of a calendar change: returned clock and recalculation-intervention count. A received response lets you display the resulting state without replaying the command.')
properties('ToolTimeChange', [
  ['clock', 'Horloge retournée après le changement, à utiliser pour afficher la date réellement obtenue.', 'Clock returned after the change, used to display the date actually obtained.'],
  ['interventions', 'Nombre d’interventions natives lors d’un recalcul de trains ; zéro pour une simple translation du calendrier. Les interventions peuvent déplacer des trains et entraîner des coûts.', 'Number of native interventions during train recalculation; zero for a simple calendar translation. Interventions may move trains and incur costs.'],
])
related = ['/mods/traductions', '/mods/metadonnees-traduites']
entry('fun:tr(String,Pair<String,Any>)', 'Prépare une référence de texte du catalogue du mod, traduite lors de l’affichage. Passez-la directement aux contrôles, sans concaténation ni tr dans les journaux. Jusqu’à huit paramètres nommés, convertis par toString ; pluriels choisis explicitement par le mod.', 'Prepares a text reference from the mod catalogue, translated when displayed. Pass it directly to controls, without concatenation or tr in logs. Up to eight named parameters, converted through toString; plural forms are chosen explicitly by the mod.')
